import {unionArea} from './geometry.js';
import {isWorkingArea} from './working-areas.js';
import {rackStats} from './racks.js';
export function editorSpaceSummary(state){const foundations=state.shapes.filter(s=>s.layer==='foundation'),sections=state.shapes.filter(s=>s.layer==='section'),total=unionArea(foundations);let assigned=0,unassigned=0;for(const section of sections){const stats=rackStats(state,section.id);assigned+=stats.assigned;unassigned+=stats.unassigned;}return {total,sections:unionArea(sections),assigned,unassigned,working:unionArea(sections.filter(isWorkingArea))};}
export function editorLegend(state,fmt){const stats=editorSpaceSummary(state),share=n=>`${fmt(stats.total?n/stats.total*100:0)}%`,item=(kind,label,value,title)=>`<span class="spaceLegendItem" title="${title}"><i class="spaceLegendIcon ${kind}" aria-hidden="true"></i><span>${label}<b>${value}</b></span></span>`;return item('foundation','Foundation',`${fmt(stats.total)} m²`,'Total foundation footprint on the active floor; overlapping foundations count once.')+item('section','Sections',share(stats.sections),'All section area as a percentage of this floor, including racks and working areas.')+item('assigned','Assigned racks',share(stats.assigned),'Assigned rack ground footprint as a percentage of this floor; tiers do not multiply ground area.')+item('unassigned','Unassigned racks',share(stats.unassigned),'Unassigned rack ground footprint as a percentage of this floor.')+item('working','Working area',share(stats.working),'Reserved working areas as a percentage of this floor. Categories overlap: sections include racks and working areas.');}
